import sys
import json
import os
import ast
import struct

def parse_vars(vars_str):
    vars_dict = {}
    for line in vars_str.split('\n'):
        line = line.strip()
        if not line:
            continue
        if '=' in line:
            var_name, var_value = line.split('=', 1)
            var_name = var_name.strip()
            var_value = var_value.strip()
            try:
                var_value = int(var_value)
            except ValueError:
                continue
            vars_dict[var_name] = var_value
    return vars_dict

def read_cache():
    if os.path.exists('cache.bin'):
        with open('cache.bin', 'rb') as f:
            data = f.read()
            if len(data) % 4 != 0:
                return None
            vars_dict = {}
            for i in range(0, len(data), 4):
                var_name_len = struct.unpack('>I', data[i:i+4])[0]
                if var_name_len == 0:
                    break
                var_name = data[i+4:i+4+var_name_len].decode('utf-8')
                var_value = struct.unpack('>I', data[i+4+var_name_len:i+4+var_name_len+4])[0]
                vars_dict[var_name] = var_value
            return vars_dict
    return None

def write_cache(vars_dict):
    with open('cache.bin', 'wb') as f:
        for var_name, var_value in vars_dict.items():
            f.write(struct.pack('>I', len(var_name)))
            f.write(var_name.encode('utf-8'))
            f.write(struct.pack('>I', var_value))

def evaluate_expression(expr, vars_dict):
    try:
        node = ast.parse(expr, mode='eval')
        return eval(compile(node, '<string>', 'eval'), {}, vars_dict)
    except:
        return 0

def render_template(template, vars_dict):
    rendered = []
    i = 0
    n = len(template)
    while i < n:
        if template[i] == '{' and i + 1 < n and template[i+1] == '{':
            j = template.find('}}', i)
            if j == -1:
                rendered.append(template[i:])
                break
            expr = template[i+2:j]
            try:
                result = evaluate_expression(expr, vars_dict)
                rendered.append(str(result))
            except:
                rendered.append(template[i:])
            i = j + 2
        else:
            rendered.append(template[i])
            i += 1
    return ''.join(rendered)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    file_path = sys.argv[1]

    if os.path.exists(file_path):
        with open(file_path, 'r') as f:
            data = json.load(f)
            if not isinstance(data, dict) or 'template' not in data or 'vars' not in data:
                sys.exit(1)
            template = data['template']
            vars_dict = data['vars']
            rendered = render_template(template, vars_dict)
            print(rendered)
            write_cache(vars_dict)
    else:
        template = sys.stdin.read()
        vars_dict = read_cache()
        if vars_dict is None:
            sys.exit(1)
        rendered = render_template(template, vars_dict)
        print(rendered)

if __name__ == '__main__':
