import sys
import json
import os
import struct
import re

def parse_vars_from_json(file_path):
    with open(file_path, 'r') as f:
        data = json.load(f)
    if not isinstance(data, dict) or 'template' not in data or 'vars' not in data:
        raise ValueError("Invalid JSON format")
    if not isinstance(data['vars'], dict):
        raise ValueError("'vars' must be a dictionary")
    return data['vars']

def evaluate_expression(expr, vars_map):
    def parse_expr(tokens):
        tokens = [t.strip() for t in tokens.split()]
        if not tokens:
            return None
        if tokens[0] == '(':
            sub_expr = parse_expr(tokens[1:])
            if not sub_expr:
                raise ValueError("Unbalanced parentheses")
            if tokens[-1] != ')':
                raise ValueError("Unbalanced parentheses")
            return sub_expr
        elif tokens[0] in vars_map:
            return vars_map[tokens[0]]
        elif tokens[0].isdigit():
            return int(tokens[0])
        else:
            raise ValueError(f"Unexpected token: {tokens[0]}")

    def parse_operator(tokens):
        if not tokens:
            return None
        if tokens[0] in '+-*/':
            return tokens[0]
        return None

    def evaluate(tokens):
        if len(tokens) == 1:
            return parse_expr(tokens)

        left = evaluate(tokens[:-1])
        op = parse_operator(tokens[-1])
        if op is None:
            raise ValueError("Invalid operator")

        if op == '+':
            right = evaluate(tokens[1:])
            return left + right
        elif op == '-':
            if len(tokens) == 2:
                return left - parse_expr(tokens[1:])
            right = evaluate(tokens[1:])
            return left - right
        elif op == '*':
            right = evaluate(tokens[1:])
            return left * right

    tokens = re.findall(r'(\d+|[a-zA-Z_][a-zA-Z0-9_]*|[-+*/()])', expr)
    return evaluate(tokens)

def render_template(template, vars_map):
    def replace_match(match):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr, vars_map)
            return str(value)
        except ValueError as e:
            raise ValueError(f"Invalid expression: {expr}") from e

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, template)

def write_cache(vars_map):
    with open('cache.bin', 'wb') as f:
        for key, value in vars_map.items():
            f.write(key.encode('utf-8'))
            f.write(b'\x00')
            f.write(struct.pack('>I', value))

def read_cache():
    vars_map = {}
    with open('cache.bin', 'rb') as f:
        while True:
            key_bytes = []
            while True:
                byte = f.read(1)
                if not byte:
                    break
                if byte == b'\x00':
                    break
                key_bytes.append(byte)
            key = ''.join(key_bytes).decode('utf-8')
            if not key:
                break
            value = struct.unpack('>I', f.read(4))[0]
            vars_map[key] = value
    return vars_map

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    file_path = sys.argv[1]

    if os.path.exists(file_path):
        try:
            vars_map = parse_vars_from_json(file_path)
            rendered = render_template(vars_map['template'], vars_map['vars'])
            print(rendered)
            write_cache(vars_map['vars'])
        except Exception as e:
            sys.exit(1)
    else:
        try:
            vars_map = read_cache()
            template = sys.stdin.read()
            rendered = render_template(template, vars_map)
            print(rendered)
        except Exception as e:
            sys.exit(1)

if __name__ == '__main__':
    main()

