def parse_expr(expr):
    tokens = re.findall(r'(\d+|[a-zA-Z_][a-zA-Z0-9_]*|[+\-*/()]|[ \t\n]+)', expr)
    tokens = [t.strip() for t in tokens if t.strip()]
    stack = []
    output = []
    operators = {'+', '-', '*'}

    for token in tokens:
        if token.isdigit():
            output.append(int(token))
        elif token in operators:
            stack.append(token)
        elif token in ('(', '['):
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Remove '('
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Remove '('
        elif token in ('+', '-', '*'):
            while stack and stack[-1] != '(' and stack[-1] in operators:
                output.append(stack.pop())
            stack.append(token)
        elif token in ('(', '['):
            stack.append(token)
        elif token in ('{', '['):
            stack.append(token)
        elif token in ('}', ']'):
            while stack and stack[-1] != '{' and stack[-1] != '[':
                output.append(stack.pop())
            stack.pop()  # Remove matching bracket
        else:
            if token in vars:
                output.append(vars[token])
            else:
                raise ValueError(f"Unknown variable: {token}")

    while stack:
        output.append(stack.pop())

    return output

def evaluate_expression(tokens):
