import sys
import json
import os
import re
from typing import Dict, Any

def validate_json(json_str: str) -> Dict[str, Any]:
    data = json.loads(json_str)
    if not isinstance(data, dict) or "template" not in data or "vars" not in data:
        raise ValueError("Invalid JSON: must contain 'template' and 'vars' keys")
    if not isinstance(data["template"], str):
        raise ValueError("'template' must be a string")
    if not isinstance(data["vars"], dict):
        raise ValueError("'vars' must be a JSON object")
    for var_name in data["vars"]:
        if not re.fullmatch(r'^[a-zA-Z][a-zA-Z0-9_]*$', var_name):
            raise ValueError(f"Invalid variable name: '{var_name}'")
    return data

def evaluate_expression(expr: str, vars: Dict[str, int]) -> int:
    try:
        # Replace variables with their values
        for var_name, var_value in vars.items():
            expr = expr.replace(var_name, str(var_value))
        # Evaluate the expression safely
        return eval(expr)
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

def render_template(template: str, vars: Dict[str, int]) -> str:
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr, vars))

    pattern = re.compile(r'\{\{([^}]+)\}\}')
    return pattern.sub(replace_match, template)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python render_cache.py <path>\n")
        sys.exit(1)

    path = sys.argv[1]

    if os.path.exists(path):
        try:
            with open(path, 'r') as f:
                json_data = f.read()
                data = validate_json(json_data)
                rendered = render_template(data["template"], data["vars"])
                print(rendered)
                with open('cache.bin', 'wb') as f:
                    json.dump(data["vars"], f)
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)
    else:
        try:
            template = sys.stdin.read().strip()
            with open('cache.bin', 'rb') as f:
                vars_data = json.load(f)
            rendered = render_template(template, vars_data)
            print(rendered)
        except FileNotFoundError:
            sys.stderr.write("Error: cache.bin not found\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)

if __name__ == "__main__":
    main()
